export function BranchOverview(n){return`\n        <div class="branch-overview-grid">\n            ${n.map(n=>{const s=n.keyFacts.map(n=>`<li>${n}</li>`).join(""),a=n.notableOperations.slice(0,3).map(n=>`<li>${n}</li>`).join("");return`\n            <div class="branch-card" style="--branch-color: ${n.color}">\n                <div class="branch-card-header">\n                    <div class="branch-emblem" style="background: ${n.color}">${n.name.split(" ").map(n=>n[0]).join("")}</div>\n                    <div>\n                        <h3>${n.name}</h3>\n                        <p class="branch-motto">${n.motto}</p>\n                    </div>\n                </div>\n                <div class="branch-card-body">\n                    <div class="branch-stats">\n                        <div class="branch-stat">\n                            <span class="stat-value">${n.strength.split(" ")[0]}</span>\n                            <span class="stat-desc">Personnel</span>\n                        </div>\n                        <div class="branch-stat">\n                            <span class="stat-value">${n.founded.split(" ").pop()}</span>\n                            <span class="stat-desc">Established</span>\n                        </div>\n                    </div>\n                    <p class="branch-overview">${n.overview}</p>\n                    <div class="branch-section">\n                        <h4>Key Facts</h4>\n                        <ul>${s}</ul>\n                    </div>\n                    <div class="branch-section">\n                        <h4>Notable Operations</h4>\n                        <ul>${a}</ul>\n                    </div>\n                    <div class="branch-chief">\n                        <span class="chief-label">Chief</span>\n                        <span class="chief-name">${n.chief}</span>\n                    </div>\n                </div>\n            </div>\n        `}).join("")}\n        </div>\n    `}